// Package winrt holds the WinRT bindings internal/ble needs that
// github.com/saltosystems/winrt-go does not ship. They were generated by its
// winrt-go-gen, run in an empty directory and moved here from
// windows/devices/{radios,bluetooth}:
//
//	winrt-go-gen -class Windows.Devices.Radios.Radio -method-filter get_State -method-filter add_StateChanged -method-filter remove_StateChanged -method-filter '!*'
//	winrt-go-gen -class Windows.Devices.Radios.RadioState
//	winrt-go-gen -class Windows.Devices.Bluetooth.BluetoothAdapter -method-filter GetDefaultAsync -method-filter get_IsLowEnergySupported -method-filter get_IsCentralRoleSupported -method-filter GetRadioAsync -method-filter '!*'
package winrt
